"""Module defining icons used in the MCP application."""

from mcp.types import Icon

# We inline the SVG as a base64-encoded data URI for simplicity. Easier that needing to serve and image from a
# location we know won't change.
driver_logo_inline = "data:image/svg+xml;base64,"
driver_logo_svg = Icon(
    src=driver_logo_inline,
    mimeType="image/svg+xml",
)
